export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"tr","term":"Piyasa emri (market order)","aka":["market emri","market order","piyasa fiyatından emir"],"short":"Piyasa emri (market order), fiyat belirtmeden verilen ve emir defterindeki en iyi mevcut fiyatlardan hemen gerçekleşen alım veya satım emridir.","body":["Piyasa emrinin önceliği hızdır: emriniz neredeyse anında dolar, ama hangi fiyattan dolacağını önceden tam bilemezsiniz. Emir defterindeki en iyi fiyatlı karşı emirlerle eşleşir ve gerekirse sonraki fiyat seviyelerine geçer.",["Piyasa emirleri defterdeki likiditeyi alır, bu yüzden genellikle daha yüksek ",["taker ücreti","maker-taker-fees"]," ödenir. Likit paritelerde ve küçük tutarlarda ",["kayma","slippage"]," önemsiz olabilir; sığ paritelerde veya ani haberlerde ise ortalama fiyat beklentinizden belirgin şekilde sapabilir."],"Bazı borsalar piyasa emrinde koruma mekanizmaları uygular, örneğin fiyatın belirli bir yüzdeden fazla kaymasını engelleyen sınırlar. Bu özellikler ve isimleri borsadan borsaya değişir; büyük işlemlerden önce borsanızın emir ayarlarını kontrol etmek yararlıdır."],"example":[["BTC","bitcoin"],"/",["USDT","usdt"],"'de en iyi satış fiyatı 61.000 USDT ve bu seviyede 0,3 BTC bekliyor; bir sonraki seviye 61.050 USDT'de 1 BTC. 0,5 BTC'lik piyasa alış emri verirseniz 0,3 BTC'yi 61.000'den (18.300 USDT), 0,2 BTC'yi 61.050'den (12.210 USDT) alırsınız. Toplam 30.510 USDT, ortalama fiyat 61.020 USDT olur. Üstüne yüzde 0,05 taker ücreti eklenirse yaklaşık 15,3 USDT daha ödersiniz."],"mistakes":["Sığ bir paritede büyük tutarlı piyasa emri verip yüksek kayma yaşamak.","Haber anlarında veya sert hareketlerde piyasa emriyle panik alım-satım yapmak.","Piyasa emrinin taker ücreti ödediğini ve limit emre göre daha pahalı olabileceğini bilmemek."],"faq":[{"q":"Piyasa emri mi limit emir mi daha iyi?","a":"Hemen işlem yapmanız gerekiyorsa piyasa emri, fiyat kontrolü istiyorsanız limit emir uygundur. Limit emir dolmayabilir; piyasa emri ise fiyat garantisi vermez."},{"q":"Piyasa emri neden farklı fiyattan doldu?","a":"Emriniz defterdeki birden fazla fiyat seviyesiyle eşleşmiş veya emir verdiğiniz anda fiyat hareket etmiş olabilir. Bu farka kayma denir."}],"title":"Piyasa emri (market order) nedir?","description":"Piyasa emrinin nasıl çalıştığını, neden anında dolduğunu ama fiyat garantisi vermediğini ve taker ücretini öğrenin.","related":[["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."],["slippage","Kayma (slippage)","Kayma (slippage), bir emrin beklenen fiyat ile gerçekte gerçekleştiği ortalama fiyat arasındaki farktır ve genellikle piyasa emirlerinde, düşük likiditede veya hızlı fiyat hareketlerinde ortaya çıkar."],["maker-taker-fees","Maker ve taker ücretleri","Maker ve taker ücretleri, borsanın emir defterine likidite ekleyen (maker) ve defterdeki emirleri anında karşılayarak likidite çeken (taker) işlemlere uyguladığı farklı komisyon oranlarıdır."],["order-book","Emir defteri (order book)","Emir defteri (order book), bir paritede bekleyen tüm alış ve satış limit emirlerinin fiyat seviyelerine ve miktarlarına göre sıralandığı, borsanın gerçek zamanlı listesidir."],["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Piyasa, limit, iptal: Her biri neyi çözer?"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"tr","term":"Arbitraj (Arbitrage)","aka":["arbitraj işlemi","borsalar arası arbitraj","arb"],"short":"Arbitraj, aynı varlığın farklı piyasalardaki fiyat farkından yararlanmak için ucuz olduğu yerden alıp pahalı olduğu yerde satma işlemidir.","body":["En basit türü borsalar arası arbitrajdır: bir coin bir borsada diğerinden ucuzsa orada alıp diğerinde satarsınız. Üçgen arbitrajda aynı borsadaki üç parite arasındaki fiyat tutarsızlığından yararlanılır. Spot ile vadeli fiyat arasındaki farkı veya fonlama oranını hedefleyen arbitraj türleri de yaygındır.",["Kâğıt üzerinde risksiz görünse de gerçekte birçok maliyet ve risk vardır: işlem ücretleri, çekim ücretleri, transfer süresince fiyatın değişmesi, ",["kayma","slippage"],", çekimlerin askıya alınması ve ağ yoğunluğu. Fiyat farkları çoğu zaman botlar tarafından saniyeler içinde kapatılır."],"Büyük ve kalıcı görünen farklar genellikle bir sebebe işaret eder; örneğin bir borsada para çekme kapalıdır ya da token farklı bir ağda işlem görür. İşleme girmeden önce iki borsadaki yatırma ve çekme durumunu kontrol edin."],"example":["Bir coin A borsasında 2,00 ",["USDT","usdt"],", B borsasında 2,06 USDT olsun. A'da 5.000 USDT'ye 2.500 coin alıp 5 USDT alım ücreti ödersiniz; toplam maliyet 5.005 USDT. ",["Çekim ücreti","withdrawal-fee"]," 10 coin. B'ye ulaşan 2.490 coini 2,06'dan satınca 5.129,4 USDT alırsınız; yaklaşık 5,1 USDT satış ücretinden sonra 5.124,3 USDT kalır. Net kâr yaklaşık 119 USDT, yani yüzde 2,4'tür. Transfer sırasında B'deki fiyat yüzde 3 düşerse bu kâr tamamen silinir."],"mistakes":["Çekim ücretini ve transfer süresini hesaba katmadan fiyat farkını net kâr sanmak.","Para yatırma veya çekme işlemleri kapalı olan bir borsadaki büyük fiyat farkını fırsat zannetmek.","Transfer için yanlış ağı seçip fonları geciktirmek ya da kaybetmek."],"faq":[{"q":"Kripto arbitraj risksiz mi?","a":"Hayır. Transfer süresince fiyat değişimi, ücretler, kayma ve borsa kaynaklı gecikmeler kârı silebilir. Risk azaltılabilir ama sıfırlanamaz."},{"q":"Arbitraj fırsatları neden çabuk kaybolur?","a":"Otomatik botlar fiyat farklarını sürekli tarar ve hızla işlem yapar. Bu işlemler fiyatları kısa sürede birbirine yaklaştırır."}],"title":"Arbitraj nedir? Kripto arbitraj nasıl çalışır","description":"Kripto arbitrajın türlerini, ücret ve transfer risklerini ve gerçek kârın nasıl hesaplandığını örnekle öğrenin.","related":[["funding-rate-arbitrage","Fonlama oranı arbitrajı (Funding rate arbitrage)","Fonlama oranı arbitrajı, spot piyasada bir coin alıp aynı miktarda perpetual short açarak fiyat riskini nötrlediğiniz ve pozitif fonlama ödemelerini topladığınız stratejidir."],["bid-ask-spread","Alış-satış makası (spread)","Alış-satış makası (spread), emir defterindeki en yüksek alış fiyatı (bid) ile en düşük satış fiyatı (ask) arasındaki farktır ve hemen alıp hemen satan birinin ödediği gizli maliyeti gösterir."],["market-maker","Piyasa yapıcı (Market maker)","Piyasa yapıcı, emir defterinde sürekli alış ve satış emirleri vererek likidite sağlayan ve kazancını çoğunlukla alış-satış makasından elde eden kişi veya şirkettir."],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"tr","term":"Sürekli vadeli kontrat (Perpetual futures)","aka":["perpetual","perp","vadesiz vadeli kontrat","sürekli kontrat"],"short":"Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir.","body":["Klasik vadeli kontratlar belirli bir tarihte kapanır. Perpetual kontratların ise vadesi yoktur; teminatınız yettiği sürece pozisyonu istediğiniz kadar açık tutabilirsiniz. Kripto borsalarında en çok işlem gören türev ürün budur.",["Vade olmadığı için kontrat fiyatının spot fiyattan uzaklaşmasını önleyen başka bir mekanizma gerekir: ",["fonlama oranı","funding-rate"],". Kontrat spotun üzerinde işlem görüyorsa long tarafı short tarafına ödeme yapar, altındaysa tersi olur. Ödemeler çoğu borsada 8 saatte bir yapılır, ancak bazı borsa ve paritelerde 1, 2 veya 4 saatlik aralıklar kullanılır."],[["Likidasyon","liquidation"]," kararları genellikle ",["son işlem","last-price"]," fiyatına değil, endeks fiyatından türetilen işaret fiyatına (mark price) göre verilir. Böylece tek bir borsadaki anlık sıçrama pozisyonunuzu tasfiye ettirmez. Binance, OKX ve Bybit gibi merkezi borsaların yanında Hyperliquid gibi zincir üstü ",["perp DEX","perp-dex"],"'ler de bu ürünü sunar."]],"example":[["ETH","ethereum"]," perpetual kontratında 2 ETH long pozisyonunuz var ve ETH 3.000 ",["USDT","usdt"],"; pozisyon değeri 6.000 USDT. Fonlama oranı 8 saatte bir yüzde 0,01 ise her ödeme döneminde 6.000 × 0,0001 = 0,6 USDT ödersiniz. Pozisyonu 30 gün açık tutarsanız 90 ödeme dönemi geçer ve oran sabit kalırsa toplam yaklaşık 54 USDT fonlama ödersiniz. Oran negatife dönerse bu kez long tarafı olarak ödeme alırsınız."],"mistakes":["Vadesi olmadığı için pozisyonu maliyetsiz sonsuza kadar tutabileceğinizi sanmak; fonlama ödemeleri birikir.","Likidasyonun son işlem fiyatına göre olduğunu düşünüp işaret fiyatını takip etmemek.","Fonlama aralığının her borsada ve her paritede 8 saat olduğunu varsaymak."],"faq":[{"q":"Perpetual ile normal vadeli kontrat arasındaki fark nedir?","a":"Normal vadeli kontratın bir vade tarihi vardır ve o gün kapanır. Perpetual kontratın vadesi yoktur, fiyatı fonlama oranıyla spota bağlı tutulur."},{"q":"Perpetual kontratta coinin sahibi olur muyum?","a":"Hayır. Yalnızca fiyat hareketine bağlı bir pozisyon tutarsınız. Coini cüzdanınıza çekmek istiyorsanız spot piyasadan almanız gerekir."}],"title":"Perpetual (sürekli vadeli kontrat) nedir? Nasıl çalışır","description":"Sürekli vadeli kontratın nasıl çalıştığını, fonlama oranını, işaret fiyatını ve tutma maliyetini öğrenin.","related":[["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["mark-price","İşaret fiyatı (Mark price)","İşaret fiyatı (mark price), vadeli işlem borsalarının gerçekleşmemiş kâr-zararı ve likidasyonu hesaplamak için kullandığı, manipülasyona karşı dengelenmiş adil fiyattır."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["futures-contract","Vadeli işlem sözleşmesi (Futures contract)","Vadeli işlem sözleşmesi, bir varlığı sahiplenmeden fiyatı üzerine işlem yapmanızı sağlayan ve iki tarafın varlığı belirli bir fiyattan ileride alıp satmayı kabul ettiği türev sözleşmedir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"tr","term":"Teslimatlı vadeli kontrat (Delivery futures)","aka":["çeyreklik vadeli kontrat","vadeli kontrat","quarterly futures"],"short":"Teslimatlı vadeli kontrat, önceden belirlenmiş bir vade tarihinde kapanan ve o gün uzlaşma fiyatı üzerinden hesaplanan kripto vadeli işlem sözleşmesidir.","body":["Bu kontratların bir son günü vardır; kriptoda en yaygın olanları haftalık, iki haftalık, çeyreklik ve iki çeyreklik vadelerdir. Vade günü açık pozisyonlar, genellikle belirli bir süredeki endeks fiyatlarının ortalamasından hesaplanan uzlaşma fiyatıyla otomatik kapatılır. Kripto borsalarında bu uzlaşma çoğunlukla nakit veya teminat coini üzerinden yapılır, fiziksel teslim olmaz.","Teslimatlı kontratlarda fonlama ödemesi yoktur. Bunun yerine kontrat fiyatı spot fiyatın üzerinde veya altında işlem görür; aradaki farka baz (basis) denir. Vade yaklaştıkça baz sıfıra doğru daralır.",["Kurumsal yatırımcılar ve madenciler bu kontratları belirli bir tarihe kadar fiyatı sabitlemek ve riskten korunmak (",["hedge","hedging"],") için kullanır. Pozisyonu vadeden sonra da sürdürmek isterseniz bir sonraki vadeye geçmeniz (rollover) gerekir. Vade takvimi ve uzlaşma yöntemi borsaya göre değişir."]],"example":[["BTC","bitcoin"]," spotta 60.000 ",["USDT","usdt"]," iken üç ay sonra sona eren çeyreklik kontrat 61.500 USDT'den işlem görüyor. Baz 1.500 USDT, yani yaklaşık yüzde 2,5'tir. 1 BTC spot alıp aynı anda 1 BTC çeyreklik kontratta short açarsanız, vade günü spot ile kontrat fiyatı buluşur. Vadede BTC 55.000 de olsa 70.000 de olsa bu kombinasyondan ücretler hariç yaklaşık 1.500 USDT elde edersiniz, çünkü iki bacağın kâr ve zararı birbirini dengeler."],"mistakes":["Vade tarihini unutup pozisyonun otomatik kapandığını sonradan fark etmek.","Teslimatlı kontrat fiyatını spot fiyatla aynı sanmak ve bazı hesaba katmamak.","Uzlaşma fiyatının son işlem fiyatı değil, bir ortalama olduğunu bilmemek."],"faq":[{"q":"Çeyreklik vadeli kontrat vade günü ne olur?","a":"Açık pozisyonlar borsanın belirlediği uzlaşma fiyatından kapatılır ve kâr veya zarar hesabınıza yansıtılır. Pozisyonu sürdürmek isterseniz bir sonraki vadede yeniden açmanız gerekir."},{"q":"Teslimatlı kontratta fonlama ücreti var mı?","a":"Hayır. Fonlama mekanizması perpetual kontratlara özgüdür. Teslimatlı kontratta tutma maliyeti, giriş anındaki baza yansır."}],"title":"Teslimatlı (çeyreklik) vadeli kontrat nedir?","description":"Çeyreklik ve teslimatlı vadeli kontratların nasıl çalıştığını, vade günü uzlaşmayı ve bazı örnekle öğrenin.","related":[["futures-contract","Vadeli işlem sözleşmesi (Futures contract)","Vadeli işlem sözleşmesi, bir varlığı sahiplenmeden fiyatı üzerine işlem yapmanızı sağlayan ve iki tarafın varlığı belirli bir fiyattan ileride alıp satmayı kabul ettiği türev sözleşmedir."],["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["futures-basis","Vadeli baz (Futures basis)","Vadeli baz, bir vadeli kontratın fiyatı ile dayanak varlığın spot fiyatı arasındaki farktır ve genellikle tutar veya yıllıklandırılmış yüzde olarak ifade edilir."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot ve vadeli işlemler: Aynı şeyi satın almıyorsunuz"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"tr","term":"Başlangıç teminatı (Initial margin)","aka":["başlangıç marjini","initial margin","açılış teminatı"],"short":"Başlangıç teminatı, kaldıraçlı bir pozisyonu açabilmek için hesabınızda bulunması ve pozisyona bağlanması gereken asgari teminat tutarıdır.","body":[["Başlangıç teminatı, pozisyonun nominal değerinin kaldıraca bölünmesiyle bulunur. 10x kaldıraçla 10.000 ",["USDT","usdt"],"'lik bir pozisyon için 1.000 USDT başlangıç teminatı gerekir. Kaldıracı artırdıkça gereken teminat azalır, ama ",["likidasyon fiyatı","liquidation-price"]," da girişe yaklaşır."],["Başlangıç teminatı ile ",["bakım teminatı","maintenance-margin"]," farklı şeylerdir. Başlangıç teminatı pozisyonu açmak için gereken tutardır; bakım teminatı ise pozisyonu açık tutmak için gereken, daha düşük asgari seviyedir. İkisi arasındaki fark, pozisyonunuzun tasfiye olmadan önce tolere edebileceği zararı belirler."],["Birçok borsa emir girerken gerekli teminatı gösterir ve açılış ücretini de bu tutara ekleyebilir. Büyük pozisyonlarda borsalar kademeli risk limitleri uygular; pozisyon büyüdükçe izin verilen ",["kaldıraç","leverage"]," düşer ve gereken başlangıç teminatı oranı yükselir."]],"example":[["ETH","ethereum"]," 2.500 USDT iken 4 ETH long açmak istiyorsunuz; nominal değer 10.000 USDT. 20x kaldıraç seçerseniz başlangıç teminatı 10.000 / 20 = 500 USDT, 5x seçerseniz 2.000 USDT olur. Bakım teminatı oranı yüzde 0,5 ise bakım teminatı 50 USDT'dir. 20x'te tasfiyeden önce yaklaşık 450 USDT, 5x'te ise yaklaşık 1.950 USDT zarara dayanabilirsiniz; bu da fiyatın yaklaşık yüzde 4,5'e karşı yüzde 19,5 düşmesi demektir."],"mistakes":["Başlangıç teminatını kaybedebileceğiniz en fazla tutar sanıp çapraz marjinde diğer bakiyelerin de risk altında olduğunu unutmak.","Düşük başlangıç teminatı gördüğü için gereğinden büyük pozisyon açmak.","Açılış ve kapanış ücretlerinin teminattan düştüğünü hesaba katmamak."],"faq":[{"q":"Başlangıç teminatı nasıl hesaplanır?","a":"Pozisyonun nominal değerini seçtiğiniz kaldıraca bölersiniz. Örneğin 5.000 USDT'lik pozisyon 10x kaldıraçta 500 USDT başlangıç teminatı gerektirir."},{"q":"Başlangıç teminatı ile bakım teminatı farkı nedir?","a":"Başlangıç teminatı pozisyonu açmak için, bakım teminatı ise açık tutmak için gereken tutardır. Teminatınız bakım seviyesinin altına inerse tasfiye başlar."}],"title":"Başlangıç teminatı (initial margin) nedir?","description":"Başlangıç teminatının nasıl hesaplandığını, kaldıraçla ilişkisini ve bakım teminatından farkını öğrenin.","related":[["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["margin-trading","Marjin ticareti (Margin trading)","Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Teminatınız sıfıra ulaşmadan önce pozisyonunuz neden kapatılabilir?"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"tr","term":"Portföy marjini (Portfolio margin)","aka":["portföy teminatı","portfolio margin","PM"],"short":"Portföy marjini, teminat gereksinimini her pozisyon için ayrı ayrı değil, tüm portföyün toplam riskine göre hesaplayan gelişmiş bir marjin modudur.","body":["Standart çapraz marjinde her pozisyonun teminat gereksinimi kabaca ayrı ayrı hesaplanıp toplanır. Portföy marjininde ise borsa, fiyatların farklı senaryolarda yükselip düştüğünü varsayarak tüm portföyün en kötü durumdaki kaybını hesaplar ve teminatı buna göre ister. Birbirini dengeleyen pozisyonlar bu sayede daha az teminat gerektirir.",["Örneğin spot ",["BTC","bitcoin"]," tutarken BTC vadeli short açtıysanız, iki pozisyon büyük ölçüde birbirini dengeler. Portföy marjini bunu tanır ve teminat yükünü düşürür. Opsiyon, vadeli ve spot pozisyonlarını birlikte yöneten profesyonel işlemciler için sermaye verimliliğini ciddi şekilde artırabilir."],["Bu mod genellikle belirli bir bakiye eşiği veya deneyim şartı gerektirir ve ",["birleşik işlem hesabı","unified-trading-account"]," içinde sunulur. Kullanılan risk modeli, stres senaryoları ve kabul edilen teminat varlıkları borsadan borsaya farklıdır. Düşük teminat gereksinimi, aynı sermayeyle çok daha büyük pozisyon açma eğilimini de beraberinde getirir."]],"example":["Elinizde 1 BTC spot var ve BTC 60.000 ",["USDT","usdt"],". Aynı anda 1 BTC'lik ",["perpetual","perpetual-futures"]," short açıyorsunuz. Standart marjinde short için 10x kaldıraçta 6.000 USDT teminat gerekebilir. Portföy marjininde borsa, fiyat yüzde 15 yükselse de düşse de spot ve short pozisyonun kâr-zararının birbirini götürdüğünü görür. Gereken teminat bu durumda yalnızca ücretleri ve küçük fiyat farklarını karşılayacak, örneğin birkaç yüz USDT seviyesine inebilir."],"mistakes":["Düşük teminat gereksinimini daha az risk olarak yorumlamak; tek yönlü pozisyonlarda risk aynı kalır.","Hedge bacaklarından birini kapatınca teminat gereksiniminin aniden yükseleceğini unutmak.","Borsanın risk modelini ve stres senaryolarını bilmeden portföy marjinine geçmek."],"faq":[{"q":"Portföy marjini ile çapraz marjin farkı nedir?","a":"Çapraz marjin bakiyeyi pozisyonlar arasında paylaştırır, ama teminatı pozisyon bazında hesaplar. Portföy marjini ise tüm pozisyonların birlikte ne kadar kaybedebileceğine bakarak teminat ister."},{"q":"Portföy marjini kimler için uygundur?","a":"Genellikle opsiyon ve vadeli işlemlerle hedge stratejileri kullanan deneyimli işlemciler için uygundur. Borsalar bu modu çoğunlukla belirli şartlara bağlar."}],"title":"Portföy marjini nedir? Kriptoda nasıl çalışır","description":"Portföy marjininin teminatı nasıl hesapladığını, hedge pozisyonlarda neden avantajlı olduğunu ve risklerini öğrenin.","related":[["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur."],["isolated-margin","İzole marjin (Isolated margin)","İzole marjin, her pozisyona ayrı bir teminat ayrıldığı ve olası kaybın yalnızca o pozisyona bağlanan teminatla sınırlı kaldığı marjin modudur."],["unified-trading-account","Birleşik işlem hesabı (UTA)","Birleşik işlem hesabı (UTA), spot, vadeli ve opsiyon gibi farklı ürünleri tek bir hesapta toplayıp tüm bakiyenizi ortak teminat olarak kullanmanıza izin veren borsa hesap yapısıdır."],["hedging","Hedge (Riskten korunma)","Hedge (riskten korunma), mevcut bir pozisyonun olası kaybını azaltmak için ters yönde ve onunla ilişkili ikinci bir pozisyon açma stratejisidir."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Çapraz teminat: Bir kayıp diğer pozisyonlarınızı neden vurabilir?"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"tr","term":"Short squeeze (Açık pozisyon sıkışması)","aka":["short sıkışması","short squeeze","short likidasyonu"],"short":"Short squeeze, fiyatın ani yükselişiyle short pozisyon sahiplerinin zararı kesmek için geri alım yapmak veya tasfiye edilmek zorunda kalması ve bu zorunlu alımların fiyatı daha da yukarı itmesidir.","body":[["Bir piyasada çok sayıda ",["short pozisyon","long-and-short"]," birikmişse, fiyattaki küçük bir yükseliş bile bu pozisyonların bir kısmını stop'a veya likidasyona sürükler. Short pozisyon kapatmak, varlığı geri almak demektir; bu alımlar fiyatı daha da yükseltir ve bir sonraki grup short'u tetikler. Böylece kısa sürede sert ve zincirleme bir yükseliş ortaya çıkar."],["Squeeze öncesinde sık görülen işaretler arasında yüksek ",["açık pozisyon","open-interest"],", belirgin şekilde negatif ",["fonlama oranı","funding-rate"]," ve kalabalık short tarafı sayılabilir. Ancak bu işaretler bir squeeze'in olacağını garanti etmez. Aynı mekanizmanın tersi long squeeze olarak düşüşte de yaşanır."],"Short squeeze sırasında fiyat çoğu zaman temel bir haber olmadan dakikalar içinde yüzde onlarca hareket edebilir, özellikle düşük likiditeli altcoinlerde. Hareket sona erdiğinde fiyat hızla geri de dönebilir."],"example":["Bir ",["altcoin","altcoin"]," 1,00 ",["USDT","usdt"],"'de işlem görüyor ve vadeli piyasada yüksek kaldıraçlı short'lar birikmiş; fonlama oranı belirgin şekilde negatif. Fiyat bir alım dalgasıyla 1,05'e çıkınca 20x short'ların ",["likidasyon","liquidation"]," seviyeleri gelmeye başlıyor. Tasfiye edilen pozisyonların zorunlu alımları fiyatı 1,12'ye, oradan da 5x short'ların likidasyon bölgesi olan 1,20 civarına taşıyor. Bir saat içinde fiyat yüzde 20 yükseliyor ve 1,00'dan 5x short açan bir işlemci teminatının neredeyse tamamını kaybediyor."],"mistakes":["Fonlama oranı çok negatifken kalabalık tarafa katılıp yüksek kaldıraçla short açmak.","Squeeze başladıktan sonra yükselişin süreceğini varsayarak tepeye yakın long açmak.","Short pozisyonda stop koymayıp likidasyonun zincirleme alım yaratacağını hesaba katmamak."],"faq":[{"q":"Short squeeze nasıl anlaşılır?","a":"Ani fiyat yükselişine eşlik eden yoğun short likidasyonları, açık pozisyonda hızlı düşüş ve fonlama oranının normale dönmesi tipik işaretlerdir. Önceden kesin olarak tahmin etmek mümkün değildir."},{"q":"Long squeeze nedir?","a":"Short squeeze'in tersidir. Fiyatın düşmesiyle long pozisyonlar tasfiye olur, zorunlu satışlar fiyatı daha da aşağı iter."}],"title":"Short squeeze nedir? Kriptoda nasıl oluşur","description":"Short squeeze'in nasıl oluştuğunu, likidasyonların fiyatı nasıl yukarı ittiğini ve öncü işaretleri öğrenin.","related":[["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["short-selling","Açığa satış (Short selling)","Açığa satış (short selling), fiyatın düşeceği beklentisiyle bir varlığı sahip olmadan satıp daha sonra daha düşük fiyattan geri alarak aradaki farktan kazanç sağlama işlemidir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["open-interest","Açık pozisyon miktarı (Open interest)","Açık pozisyon miktarı (open interest), bir vadeli işlem veya opsiyon piyasasında henüz kapatılmamış toplam kontrat sayısını ya da değerini gösterir."]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"tr","term":"USDC (USD Coin)","aka":["USD Coin","USDC","Circle USDC"],"short":"USDC (USD Coin), Circle tarafından çıkarılan, nakit ve kısa vadeli ABD hazine bonolarıyla desteklenen ve değerini 1 ABD dolarına sabitlemeyi amaçlayan bir stablecoin'dir.","body":[["Circle, USDC rezervlerinin bileşimi hakkında düzenli raporlar yayınlar ve rezervlerin büyük kısmını düzenlenmiş finans kuruluşlarında tutar. USDC, şeffaflığı ve düzenleyici uyumu nedeniyle kurumsal kullanıcılar ve ",["DeFi","defi"]," protokolleri tarafından yaygın biçimde tercih edilir. Circle, USDC'nin AB'de ",["MiCA","mica"]," kurallarına uygun şekilde sunulduğunu açıklamıştır."],["USDC; ",["Ethereum","ethereum"],", Solana, Base, Arbitrum, Polygon ve başka ağlarda yerel olarak çıkarılır. Circle'ın CCTP adlı sistemi, USDC'yi bir ağda yakıp başka bir ağda yeniden basarak köprü token'ı yerine yerel USDC taşımaya olanak tanır. Bazı ağlarda eski köprülenmiş versiyonlar (USDC.e gibi) da bulunabilir; bunlar yerel USDC ile aynı değildir."],["USDC de ",["depeg","depeg"]," riskinden muaf değildir. 2023'te bir ABD bankasının çöküşü sırasında rezervlerin bir kısmının o bankada olması nedeniyle USDC kısa süreliğine 1 doların altına düştü ve sonra toparlandı. Circle da belirli adreslerdeki USDC'yi dondurabilir."]],"example":["Arbitrum'da 2.000 USDC ile bir DeFi protokolüne yatırma yapmak istiyorsunuz. Cüzdanınızda hem yerel USDC hem de köprülenmiş USDC.e var. Protokol yalnızca yerel USDC'yi kabul ediyorsa 2.000 USDC.e'nizi önce bir ",["DEX","dex"],"'te yerel USDC'ye çevirmeniz gerekir; takas ücreti yüzde 0,01 ise 0,2 USDC ödersiniz ve 1.999,8 USDC elde edersiniz. Token sözleşme adresini kontrol etmek bu karışıklığı önler."],"mistakes":["Yerel USDC ile köprülenmiş USDC versiyonlarını aynı sanmak.","USDC'nin hiçbir koşulda 1 doların altına düşmeyeceğini varsaymak.","Bir borsanın USDC'yi hangi ağlarda desteklediğini kontrol etmeden çekim yapmak."],"faq":[{"q":"USDC ile USDT arasındaki fark nedir?","a":"İkisi de dolara sabitlenmeyi amaçlar ama farklı şirketler tarafından çıkarılır, rezerv raporlama yöntemleri ve düzenleyici durumları farklıdır. Borsalarda likidite ve desteklenen ağlar da değişir."},{"q":"USDC.e nedir?","a":"Bazı ağlarda Ethereum'dan köprüyle getirilmiş USDC versiyonudur. Circle'ın yerel olarak çıkardığı USDC'den farklı bir token'dır."}],"title":"USDC nedir? Circle'ın stablecoin'i nasıl çalışır?","description":"USDC'nin nasıl desteklendiğini, yerel ve köprülenmiş versiyonlarını, CCTP'yi ve depeg riskini öğrenin.","related":[["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["usdt","USDT (Tether)","USDT (Tether), Tether şirketi tarafından çıkarılan, değerini 1 ABD dolarına sabitlemeyi amaçlayan ve kripto piyasalarında en yaygın kullanılan stablecoin'dir."],["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."],["mica","MiCA (AB Kripto Varlık Piyasaları Tüzüğü)","MiCA (Markets in Crypto-Assets), Avrupa Birliği'nde kripto varlık ihraççıları, stablecoin'ler ve kripto hizmet sağlayıcıları için ortak kurallar koyan kapsamlı AB düzenlemesidir."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"tr","term":"Launchpool","aka":["launchpool","token kazanma havuzu","Binance Launchpool"],"short":"Launchpool, borsanın belirli coin'leri veya stablecoin'leri havuzda kilitleyen kullanıcılara, yeni listelenecek bir projenin token'larını belirli bir süre boyunca ücretsiz dağıttığı programdır.","body":[["Binance Launchpool bu modelin en bilinen örneğidir; Bybit, Bitget, OKX ve diğer borsaların da benzer programları vardır. Kullanıcı BNB, ",["USDT","usdt"]," veya borsanın kendi token'ı gibi varlıkları havuza yatırır. Proje belirli sayıda token'ı ödül olarak ayırır ve bu ödüller havuzdaki payınıza göre saatlik veya günlük dağıtılır."],"Ana varlığınızı satmazsınız; süre bitince veya istediğiniz zaman çekebilirsiniz. Kural ve kilit süreleri programa göre değişir. Bu yüzden launchpool, elinde zaten havuz varlığı bulunanlar için ek getiri gibi görünür.",["Gerçek getiri iki şeye bağlıdır: havuza ne kadar toplam varlık geldiği ve dağıtılan token'ın listelendikten sonraki fiyatı. Yeni token'lar ",["listeleme","token-listing"]," sonrası çok oynak olabilir. Ayrıca havuz varlığının kendi fiyatı da düşebilir."]],"example":"Bir launchpool'da USDT havuzuna 30 gün boyunca 3.000.000 yeni token dağıtıldığını ve havuzda toplam 300 milyon USDT bulunduğunu varsayalım. Siz 3.000 USDT yatırırsanız payınız yüzde 0,001 olur. Toplam ödülünüz 30 adet token eder. Token listelendikten sonra 0,40 dolardan işlem görürse 12 dolar kazanırsınız, 3.000 dolar için 30 günde yaklaşık yüzde 0,4. Token 0,10 dolara düşerse ödülünüz 3 dolara iner.","mistakes":["Havuzdaki toplam yatırım miktarını hesaba katmadan beklenen ödülü abartmak.","Sadece launchpool'a katılmak için oynak bir havuz token'ı alıp fiyat düşüşüne maruz kalmak.","Dağıtılan token'ın listeleme sonrası fiyatını kesin bir değer gibi görmek."],"faq":[{"q":"Launchpool nasıl para kazandırır?","a":"Havuza yatırdığınız varlıklara karşılık yeni bir projenin token'larını ödül olarak alırsınız. Bu token'ları satabilir veya tutabilirsiniz; değerleri piyasa fiyatına bağlıdır."},{"q":"Launchpool'da yatırdığım para kilitlenir mi?","a":"Birçok programda istediğiniz zaman çekebilirsiniz, ancak bazı havuzlarda kilit süresi olabilir. Katılmadan önce program kurallarını okumak gerekir."}],"title":"Launchpool nedir? Yeni token kazanma havuzu","description":"Launchpool nedir, havuza yatırdığınız varlıklarla yeni token ödülleri nasıl hesaplanır ve gerçek getiriyi neler belirler, öğrenin.","related":[["launchpad","Launchpad (token satışı)","Launchpad, bir borsanın veya platformun yeni bir projenin token'larını listelemeden önce kullanıcılara belirli bir fiyattan sattığı token satış platformudur; borsa üzerinden yapılan satışa IEO da denir."],["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["airdrop","Airdrop","Airdrop, bir projenin token'larını belirli koşulları sağlayan cüzdanlara veya kullanıcılara ücretsiz olarak dağıtmasıdır; genellikle erken kullanıcıları ödüllendirmek ve token'ı geniş bir kitleye yaymak amacıyla yapılır."],["token-listing","Token listelemesi","Token listelemesi, bir kripto varlığın bir borsada işlem çiftleriyle alınıp satılabilir hâle getirilmesi, yani borsanın o token için yatırma, çekim ve işlem hizmeti açmasıdır."]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
